create or replace function public.is_squad_member(target_squad bigint) returns boolean language sql stable security definer set search_path=pg_catalog,public as $$ select auth.uid() is not null and exists(select 1 from public.squad_members where squad_id=target_squad and user_id=auth.uid()); $$;
create or replace function public.shares_squad(target_user uuid) returns boolean language sql stable security definer set search_path=pg_catalog,public as $$ select target_user is not null and auth.uid() is not null and exists(select 1 from public.squad_members mine join public.squad_members peer on peer.squad_id=mine.squad_id where mine.user_id=auth.uid() and peer.user_id=target_user); $$;
alter table public.profiles enable row level security; alter table public.daily_tasks enable row level security; alter table public.goals enable row level security; alter table public.check_ins enable row level security; alter table public.points_events enable row level security; alter table public.squads enable row level security; alter table public.squad_members enable row level security; alter table public.squad_activity enable row level security;
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or public.shares_squad(id)); create policy profiles_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy tasks_own_select on public.daily_tasks for select to authenticated using(user_id=auth.uid()); create policy tasks_own_insert on public.daily_tasks for insert to authenticated with check(user_id=auth.uid()); create policy tasks_own_update on public.daily_tasks for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy tasks_own_delete on public.daily_tasks for delete to authenticated using(user_id=auth.uid());
create policy goals_own_select on public.goals for select to authenticated using(user_id=auth.uid()); create policy goals_own_insert on public.goals for insert to authenticated with check(user_id=auth.uid()); create policy goals_own_update on public.goals for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy goals_own_delete on public.goals for delete to authenticated using(user_id=auth.uid());
create policy checkins_own_select on public.check_ins for select to authenticated using(user_id=auth.uid()); create policy points_own_select on public.points_events for select to authenticated using(user_id=auth.uid()); create policy squads_member_select on public.squads for select to authenticated using(public.is_squad_member(id)); create policy members_member_select on public.squad_members for select to authenticated using(public.is_squad_member(squad_id)); create policy members_leave on public.squad_members for delete to authenticated using(user_id=auth.uid()); create policy activity_member_select on public.squad_activity for select to authenticated using(public.is_squad_member(squad_id));
revoke all on all tables in schema public from anon,public,authenticated; grant select on all tables in schema public to authenticated; grant update(name) on public.profiles to authenticated; grant insert,delete on public.daily_tasks,public.goals to authenticated; revoke update on public.daily_tasks,public.goals from authenticated; grant update(title,category,task_date) on public.daily_tasks to authenticated; grant update(category,title,due_date,icon) on public.goals to authenticated; revoke insert,update,delete on public.check_ins,public.points_events,public.squads,public.squad_members,public.squad_activity from anon,authenticated; revoke execute on function public.generate_invite_code(),public.handle_new_user(),public.ensure_invite_code(),public.is_squad_member(bigint),public.shares_squad(uuid) from public,anon; grant execute on function public.is_squad_member(bigint),public.shares_squad(uuid) to authenticated;
